 namespace MyApp.Evaluation;

 [TestClass]
 public class EvaluationTests
 {
     private static ReportingConfiguration? s_reportingConfiguration;
     private static IChatClient? s_chatClient;

     [ClassInitialize]
     public static void ClassInitialize(TestContext context)
     {
         s_chatClient = CreateChatClient();
         s_reportingConfiguration = CreateReportingConfiguration(s_chatClient);
     }

     [ClassCleanup]
     public static void ClassCleanup()
     {
         s_chatClient?.Dispose();
     }

     [TestMethod]
     public async Task Chat_Responds_Relevantly()
     {
         await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
             scenarioName: nameof(Chat_Responds_Relevantly));

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "What is the capital of France?")
         };

         var response = await s_chatClient!.GetResponseAsync(messages);

         await scenario.EvaluateAsync(messages, response);
     }

