     public async Task Chat_Responds_Coherently()
     {
         await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
             scenarioName: nameof(Chat_Responds_Coherently));

         var messages = new List<ChatMessage>
         {
             new(ChatRole.System, "You are a helpful assistant that answers questions concisely."),
             new(ChatRole.User, "Explain what an API is in one sentence.")
         };

         var response = await s_chatClient!.GetResponseAsync(messages);

         await scenario.EvaluateAsync(messages, response);
     }

     private static IChatClient CreateChatClient()
     {
         var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
             ?? throw new InvalidOperationException(
                 "Set AZURE_OPENAI_ENDPOINT environment variable to the Azure OpenAI endpoint URL.");

         var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
             ?? throw new InvalidOperationException(
                 "Set AZURE_OPENAI_KEY environment variable to the Azure OpenAI API key.");

         var deploymentName = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "chat";

         var azureClient = new AzureOpenAIClient(
             new Uri(endpoint),
             new ApiKeyCredential(key));

         return azureClient.GetChatClient(deploymentName).AsIChatClient();
     }

     private static ReportingConfiguration CreateReportingConfiguration(IChatClient chatClient)
     {
         var storagePath = Path.Combine(
             Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
             "eval-results");

         var chatConfiguration = new ChatConfiguration(chatClient);

         var evaluators = new IEvaluator[]
         {
             new RelevanceEvaluator(),
             new CoherenceEvaluator(),
             new FluencyEvaluator(),
         };

         return DiskBasedReportingConfiguration.Create(
             storagePath,
             evaluators: evaluators,
             chatConfiguration: chatConfiguration);
     }
 }

